import { LUCIDE_ICON_BODIES } from "./generated-icons.js";

// All UI icons are selected from lucide-static. Geometry is generated by scripts/generate-icons.mjs.
export const ICON_NAMES = Object.freeze([
  "theater",
  "images",
  "info",
  "minus",
  "plus",
  "expand",
  "arrow-up",
  "crosshair",
  "arrow-right",
  "arrow-left",
  "shuffle",
  "armchair",
  "box",
  "rotate-ccw",
  "sun",
  "settings-2",
  "maximize",
  "move-horizontal",
  "download",
  "external-link",
  "x",
  "chevron-down",
  "check",
  "circle",
]);

export function icon(name, sprite = "./icons.svg") {
  if (!ICON_NAMES.includes(name))
    throw new Error("Unknown Lucide icon: " + name);
  return `<svg class="icon" data-icon="${name}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="${sprite}#${name}"></use></svg>`;
}

export function iconButtonContent(name, label) {
  return `${icon(name)}<span class="sr-only button-label">${label}</span>`;
}

export function iconDataUri(name, stroke = "#eee9df", strokeWidth = 2) {
  if (!ICON_NAMES.includes(name))
    throw new Error("Unknown Lucide icon: " + name);
  const body = LUCIDE_ICON_BODIES[name] || "";
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="${stroke}" stroke-width="${strokeWidth}" stroke-linecap="round" stroke-linejoin="round">${body}</svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}
